"""Build point-group operation matrices from textbook generators (independent of pgmol)."""
import math
import numpy as np

def rot(axis, ang):
    u = np.asarray(axis, float); u = u/np.linalg.norm(u)
    K = np.array([[0,-u[2],u[1]],[u[2],0,-u[0]],[-u[1],u[0],0]])
    return math.cos(ang)*np.eye(3) + math.sin(ang)*K + (1-math.cos(ang))*np.outer(u,u)

def refl(n):
    u = np.asarray(n, float); u = u/np.linalg.norm(u)
    return np.eye(3) - 2*np.outer(u,u)

def improper(axis, ang):
    return rot(axis, ang) @ refl(axis)

I3 = np.eye(3); INV = -np.eye(3)
Z = (0,0,1.); X = (1.,0,0)

def close(gens, cap=200):
    ops = [I3]
    def has(m):
        return any(np.abs(o-m).max() < 1e-7 for o in ops)
    for g in gens:
        if not has(g): ops.append(g)
    i = 0
    while i < len(ops):
        for j in range(len(ops)):
            p = ops[i] @ ops[j]
            if not has(p):
                ops.append(p)
                if len(ops) > cap: raise RuntimeError("group too big")
        i += 1
    return ops

PHI = (1+5**0.5)/2

def group(label):
    """Return operation matrices for a Schoenflies label."""
    if label in ("T","Th","Td","O","Oh","I","Ih"):
        if label.startswith("T"):
            g = [rot(Z, math.pi), rot((1,1,1), 2*math.pi/3)]
            if label == "Th": g.append(INV)
            if label == "Td": g.append(refl((1,-1,0)))
        elif label.startswith("O"):
            g = [rot(Z, math.pi/2), rot((1,1,1), 2*math.pi/3)]
            if label == "Oh": g.append(INV)
        else:
            g = [rot((0,1,PHI), 2*math.pi/5), rot(X, math.pi)]
            if label == "Ih": g.append(INV)
        return close(g)
    if label == "C1": return [I3]
    if label == "Cs": return close([refl(Z)])
    if label == "Ci": return close([INV])
    fam = label[0]; suf = label[-1] if label[-1].isalpha() else ""
    n = int(label[1:len(label)-len(suf)])
    if fam == "S": return close([improper(Z, 2*math.pi/n)])
    if fam == "C":
        g = [rot(Z, 2*math.pi/n)]
        if suf == "v": g.append(refl((0,1,0)))
        if suf == "h": g.append(refl(Z))
        return close(g)
    if fam == "D":
        if suf == "d":
            g = [improper(Z, math.pi/n), rot(X, math.pi)]
        else:
            g = [rot(Z, 2*math.pi/n), rot(X, math.pi)]
            if suf == "h": g.append(refl(Z))
        return close(g)
    raise ValueError(label)
