// Minimal Chrome DevTools Protocol client: opens the page, waits for the
// worker to report ready, then exercises it the way a user would.
const BASE = process.argv[2];           // page URL
const CDP  = process.argv[3];           // http://127.0.0.1:9222

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function newTab(url) {
  const r = await fetch(`${CDP}/json/new?${encodeURIComponent(url)}`, { method: "PUT" });
  return r.json();
}

function connect(wsUrl) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(wsUrl);
    ws.onopen = () => resolve(ws);
    ws.onerror = (e) => reject(new Error("ws error " + e.message));
  });
}

let nextId = 1;
function send(ws, method, params = {}) {
  const id = nextId++;
  return new Promise((resolve, reject) => {
    const onMsg = (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id === id) {
        ws.removeEventListener("message", onMsg);
        msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
      }
    };
    ws.addEventListener("message", onMsg);
    ws.send(JSON.stringify({ id, method, params }));
  });
}

async function evaluate(ws, expression) {
  const res = await send(ws, "Runtime.evaluate", {
    expression, awaitPromise: true, returnByValue: true,
  });
  if (res.exceptionDetails) throw new Error(res.exceptionDetails.text + " " +
    (res.exceptionDetails.exception?.description || ""));
  return res.result.value;
}

const tab = await newTab(BASE);
const ws = await connect(tab.webSocketDebuggerUrl);
const errors = [];
ws.addEventListener("message", (ev) => {
  const m = JSON.parse(ev.data);
  if (m.method === "Runtime.consoleAPICalled" && m.params.type === "error") {
    errors.push(m.params.args.map((a) => a.value ?? a.description).join(" "));
  }
  if (m.method === "Runtime.exceptionThrown") {
    errors.push(m.params.exceptionDetails.text);
  }
});
await send(ws, "Runtime.enable");
await send(ws, "Page.enable");

// Wait for the worker to finish booting Pyodide and installing the wheel.
let status = "";
for (let i = 0; i < 180; i++) {
  status = await evaluate(ws, "document.getElementById('status').dataset.state");
  if (status === "ready" || status === "failed") break;
  if (i % 20 === 0) {
    const t = await evaluate(ws, "document.getElementById('status-text').textContent");
    console.log(`  [${i}s] ${t}`);
  }
  await sleep(1000);
}
console.log("status:", status, "|", await evaluate(ws, "document.getElementById('status-text').textContent"));
if (status !== "ready") { console.log("ERRORS:", errors); process.exit(1); }

async function analyse(label, text, tolerance) {
  await evaluate(ws, `(() => {
    document.getElementById('text').value = ${JSON.stringify(text)};
    document.getElementById('tolerance').value = ${JSON.stringify(String(tolerance))};
    document.getElementById('run').click();
  })()`);
  for (let i = 0; i < 120; i++) {
    const busy = await evaluate(ws, "document.getElementById('run').disabled");
    if (!busy) break;
    await sleep(500);
  }
  const out = await evaluate(ws, `({
    label: (document.querySelector('#result-body .label')||{}).textContent || null,
    err: (document.querySelector('#result-body .error pre')||{}).textContent || null,
    notes: [...document.querySelectorAll('#result-body .note')].map(n=>n.textContent.slice(0,60)),
    facts: [...document.querySelectorAll('#result-body .fact')].map(f=>f.textContent),
    ops: (document.querySelector('#result-body .ops')||{}).textContent || null
  })`);
  console.log(`\n== ${label} ==`);
  console.log("  label:", JSON.stringify(out.label), "| err:", out.err ? JSON.stringify(out.err.slice(0,90)) : null);
  if (out.facts.length) console.log("  facts:", out.facts.join(" | "));
  if (out.ops) console.log("  ", out.ops.trim());
  if (out.notes.length) console.log("  notes:", out.notes);
  return out;
}

